using System.Data; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class ShopPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetProducts() { return new { success = true, data = DbHelper.ToDictionaryList(DbHelper.ExecuteDataTable(@"SELECT TOP 24 p.ProductID, p.ProductName, p.Description, p.Price, p.StockQuantity, c.CategoryName FROM Products p INNER JOIN ProductCategories c ON c.CategoryID = p.CategoryID WHERE p.IsActive = 1 ORDER BY p.ProductName", CommandType.Text)) }; } } }
